@section('script')
<script>(()=>{const search=document.getElementById('market-search'),cards=[...document.querySelectorAll('#market-grid .gsk-v3-market-item')],empty=document.getElementById('no-markets'),filters=[...document.querySelectorAll('[data-market-filter]')];if(!search||!cards.length)return;let active='all';const apply=()=>{const q=search.value.trim().toLocaleLowerCase();let count=0;cards.forEach(card=>{const match=(!q||card.textContent.toLocaleLowerCase().includes(q))&&(active==='all'||card.dataset.resultState===active);card.hidden=!match;if(match)count++;});if(empty)empty.hidden=count!==0;};filters.forEach(button=>button.addEventListener('click',()=>{active=button.dataset.marketFilter||'all';filters.forEach(item=>{const selected=item===button;item.classList.toggle('is-active',selected);item.setAttribute('aria-pressed',selected?'true':'false');});apply();}));search.addEventListener('input',apply,{passive:true});})();</script>
